// a line from a to b carried on past both ends (so a wide stroke's square ends lie outside the field)
const longLine = (a, b, k = 3) => { const dx = b[0] - a[0], dy = b[1] - a[1]; return [[a[0] - dx * k, a[1] - dy * k], [b[0] + dx * k, b[1] + dy * k]]; };

